fn mul(a:u16,b:u16)u16{const x:u64=if(a==0)65536 else a;const y:u64=if(b==0)65536 else b;const z=(x*y)%65537;return if(z==65536)0 else @intCast(z);}
fn add(a:u16,b:u16)u16{return @truncate(@as(u32,a)+@as(u32,b));}
fn expand(key:[16]u8) [52]u16 {var state:[8]u16=undefined;for(0..8)|i|state[i]=(@as(u16,key[2*i])<<8)|key[2*i+1];var z:[52]u16=undefined;var off:usize=0;while(off<52):(off+=8){const count:@TypeOf(off)=@min(8,52-off);for(0..count)|i|z[off+i]=state[i];var rotated:[8]u16=undefined;for(0..8)|i|rotated[i]=@truncate((@as(u32,state[(i+1)&7])<<9)|(@as(u32,state[(i+2)&7])>>7));state=rotated;}return z;}
fn encrypt(z:[52]u16,block:[8]u8)[8]u8{var x1=(@as(u16,block[0])<<8)|block[1];var x2=(@as(u16,block[2])<<8)|block[3];var x3=(@as(u16,block[4])<<8)|block[5];var x4=(@as(u16,block[6])<<8)|block[7];for(0..8)|r|{const k=r*6;const a=mul(x1,z[k]);const b=add(x2,z[k+1]);const c=add(x3,z[k+2]);const d=mul(x4,z[k+3]);const p=mul(a^c,z[k+4]);const q=mul(add(b^d,p),z[k+5]);const t=add(p,q);x1=a^q;x2=c^q;x3=b^t;x4=d^t;}const words=[_]u16{mul(x1,z[48]),add(x3,z[49]),add(x2,z[50]),mul(x4,z[51])};var out:[8]u8=undefined;for(0..4)|i|{out[2*i]=@truncate(words[i]>>8);out[2*i+1]=@truncate(words[i]);}return out;}
export fn idea_cfb64(raw:?[*]const i64,n:usize,raw_out:?[*]u8,cap:usize)i64{if(raw==null or n<27 or n>51)return -1;const v=raw.?[0..n];const mode=v[0];const lv=v[1];if(mode<0 or mode>1 or lv<1 or lv>24 or n!=26+@as(usize,@intCast(lv)))return -1;const len:usize=@intCast(lv);var key:[16]u8=undefined;var state:[8]u8=undefined;var text:[24]u8=undefined;for(0..16)|i|{if(v[2+i]<0 or v[2+i]>255)return -1;key[i]=@intCast(v[2+i]);}for(0..8)|i|{if(v[18+i]<0 or v[18+i]>255)return -1;state[i]=@intCast(v[18+i]);}for(0..len)|i|{if(v[26+i]<0 or v[26+i]>255)return -1;text[i]=@intCast(v[26+i]);}const z=expand(key);var result:[24]u8=@splat(0);var pos:usize=0;while(pos<len){const stream=encrypt(z,state);const take=@min(8,len-pos);for(0..take)|j|{result[pos+j]=text[pos+j]^stream[j];state[j]=if(mode==0) result[pos+j] else text[pos+j];}pos+=take;}if(raw_out==null or cap<len)return -2;const out=raw_out.?;for(0..len)|i|out[i]=result[i];return @intCast(len);}
